BEGIN;
DO $t$
DECLARE u bigint:=180753266;v bigint;r jsonb;o jsonb;o2 jsonb;p jsonb;cnt int:=0;
BEGIN
 DELETE FROM vilqa.nav_messages WHERE user_id=u;DELETE FROM vilqa.nav_operations WHERE user_id=u;DELETE FROM vilqa.nav_state_events WHERE user_id=u;DELETE FROM vilqa.nav_events WHERE user_id=u;DELETE FROM vilqa.nav_sessions WHERE user_id=u;
 p:='{"screen":"main","kind":"text","text":"Menu","keyboard":[{"row":{"buttons":[{"text":"Recipe","additionalFields":{"callback_data":"recipe_create"}}]}}]}'::jsonb;
 r:=vilqa.nav_ingress(u,'e1','','0','/menu');IF r->>'allowed'<>'true' THEN RAISE EXCEPTION 'initial access';END IF;cnt:=cnt+1;
 r:=vilqa.nav_ingress(u,'e1','','0','/menu');IF r->>'reason'<>'duplicate' THEN RAISE EXCEPTION 'ingress duplicate';END IF;cnt:=cnt+1;
 o:=vilqa.nav_request(u,'r1',p);IF o->>'method'<>'text' THEN RAISE EXCEPTION 'initial send';END IF;cnt:=cnt+1;
 r:=vilqa.nav_request(u,'r2',p);IF r IS NOT NULL THEN RAISE EXCEPTION 'concurrent sender';END IF;cnt:=cnt+1;
 PERFORM vilqa.nav_request(u,'r3',p);PERFORM vilqa.nav_finish((o->>'id')::bigint,100);
 IF (SELECT current_message FROM vilqa.nav_sessions WHERE user_id=u)<>100 THEN RAISE EXCEPTION 'commit sent ID';END IF;cnt:=cnt+1;
 o2:=vilqa.nav_claim(u);IF o2->>'event_key'<>'r3' THEN RAISE EXCEPTION 'coalesce';END IF;cnt:=cnt+1;
 IF (SELECT status FROM vilqa.nav_operations WHERE user_id=u AND event_key='r2')<>'superseded' THEN RAISE EXCEPTION 'superseded request';END IF;cnt:=cnt+1;
 IF o2->>'method'<>'edit' THEN RAISE EXCEPTION 'edit navigation';END IF;cnt:=cnt+1;
 r:=vilqa.nav_finish((o2->>'id')::bigint,NULL,'edit_missing');IF r->>'status'<>'retry' OR r->'retry'->>'method'<>'text' THEN RAISE EXCEPTION 'explicit edit fallback';END IF;cnt:=cnt+1;
 PERFORM vilqa.nav_finish((o2->>'id')::bigint,101);
 IF NOT (SELECT retired FROM vilqa.nav_messages WHERE user_id=u AND message_id=100) THEN RAISE EXCEPTION 'retire old';END IF;cnt:=cnt+1;
 IF (SELECT retired FROM vilqa.nav_messages WHERE user_id=u AND message_id=101) THEN RAISE EXCEPTION 'preserve current';END IF;cnt:=cnt+1;
 v:=(SELECT revision FROM vilqa.nav_sessions WHERE user_id=u);
 r:=vilqa.nav_ingress(u,'old','n:'||(o->>'revision')||':recipe_create',100,'');IF r->>'reason'<>'stale' THEN RAISE EXCEPTION 'stale button';END IF;cnt:=cnt+1;
 r:=vilqa.nav_ingress(u,'forged','n:'||v||':recipe_delete_confirm',101,'');IF r->>'reason'<>'stale' THEN RAISE EXCEPTION 'forged action';END IF;cnt:=cnt+1;
 r:=vilqa.nav_ingress(u,'valid','n:'||v||':recipe_create',101,'');IF r->>'action'<>'recipe_create' THEN RAISE EXCEPTION 'valid action';END IF;cnt:=cnt+1;
 r:=vilqa.nav_ingress(u,'legacy','recipe_ready',101,'');IF r->>'reason'<>'stale' THEN RAISE EXCEPTION 'unsafe legacy';END IF;cnt:=cnt+1;
 r:=vilqa.nav_ingress(u,'meal','meal_confirm:known',999,'');IF r->>'allowed'<>'true' THEN RAISE EXCEPTION 'meal independent';END IF;cnt:=cnt+1;
 r:=vilqa.nav_profile(u,'{"name":"Test","current_state":"recipe_ingredients","state_data":"{\"recipe_draft\":{\"recipe_name\":\"Soup\",\"ingredients_raw\":[\"potato\"]}}"}');
 IF r->>'current_state'<>'' OR NOT ((r->>'state_data')::jsonb ? 'recipe_draft') THEN RAISE EXCEPTION 'pause survives import';END IF;cnt:=cnt+1;
 v:=(r->>'_recipe_version')::bigint;
 r:=vilqa.nav_state_write(u,'resume',v,NULL,NULL,'resume');IF r->>'current_state'<>'recipe_ingredients' THEN RAISE EXCEPTION 'resume';END IF;cnt:=cnt+1;
 v:=(r->>'_recipe_version')::bigint;r:=vilqa.nav_state_write(u,'pause',v,NULL,NULL,'pause');IF r->>'current_state'<>'' OR NOT ((r->>'state_data')::jsonb ? 'recipe_draft') THEN RAISE EXCEPTION 'pause preserve';END IF;cnt:=cnt+1;
 r:=vilqa.nav_state_write(u,'late',v,'','{}','finished');IF r->>'stale_job'<>'true' THEN RAISE EXCEPTION 'stale AI guard';END IF;cnt:=cnt+1;
 r:=vilqa.nav_state_write(u,'create-existing',v+1,NULL,NULL,'start');IF r->>'existing_draft'<>'true' THEN RAISE EXCEPTION 'create cannot overwrite';END IF;cnt:=cnt+1;
 r:=vilqa.nav_ingress(u,'changed-draft','n:'||(SELECT revision FROM vilqa.nav_sessions WHERE user_id=u)||':recipe_create',101,'');IF r->>'reason'<>'stale' THEN RAISE EXCEPTION 'same message cannot act on a changed draft';END IF;cnt:=cnt+1;
 o:=vilqa.nav_request(u,'unknown',p||'{"replace":true}');PERFORM vilqa.nav_finish((o->>'id')::bigint,NULL,'unknown');
 IF (SELECT current_message FROM vilqa.nav_sessions WHERE user_id=u)<>101 THEN RAISE EXCEPTION 'unknown preserve current';END IF;cnt:=cnt+1;
 IF vilqa.nav_request(u,'unknown',p) IS NOT NULL THEN RAISE EXCEPTION 'unknown not replayed';END IF;cnt:=cnt+1;
 o:=vilqa.nav_request(u,'after-unknown',p);PERFORM vilqa.nav_finish((o->>'id')::bigint,NULL,'failed');
 IF (SELECT current_message FROM vilqa.nav_sessions WHERE user_id=u)<>101 THEN RAISE EXCEPTION 'failed preserve current';END IF;cnt:=cnt+1;
 IF vilqa.nav_request(999999999,'denied',p) IS NOT NULL THEN RAISE EXCEPTION 'denied nav';END IF;cnt:=cnt+1;
 o:=vilqa.nav_request(u,'retire','{"kind":"retire","screen":"retire"}');PERFORM vilqa.nav_finish((o->>'id')::bigint,NULL);
 IF (SELECT current_message FROM vilqa.nav_sessions WHERE user_id=u) IS NOT NULL THEN RAISE EXCEPTION 'stats retirement';END IF;cnt:=cnt+1;
 o:=vilqa.nav_register_executor(vilqa.nav_request(u,'recovery',p),'navigation-test-executor');
 IF vilqa.nav_release_failed('another-executor')<>0 THEN RAISE EXCEPTION 'wrong executor released';END IF;cnt:=cnt+1;
 IF vilqa.nav_release_failed('navigation-test-executor')<>1 THEN RAISE EXCEPTION 'failed executor not released';END IF;cnt:=cnt+1;
 IF (SELECT status FROM vilqa.nav_operations WHERE id=(o->>'id')::bigint)<>'unknown' THEN RAISE EXCEPTION 'failed executor blindly retried';END IF;cnt:=cnt+1;
 RAISE NOTICE 'navigation SQL checks: %',cnt;
END
$t$;
SELECT 'navigation SQL checks passed' AS result;
ROLLBACK;
